cd /tmp/mscratch && cat > t2.mi <<'EOF'
use system.fs
use system.os
use system.collections.list
fn main() int
    let args = Args()
    let fs = Fs()
    match fs.read_file(args.element_at(0))
        Result.Ok(text): println(f"ok [{text}]")
        Result.Err(e): println("err")
    let parts = "ledger 7".split(" ")
    println(f"{parts.length()} [{parts.element_at(1)}] {parts.element_at(1).to_int() ?? -5}")
    var fields = List<String>()
    for part in "ledger 7".split(" ")
        if not part.is_empty()
            fields.push(part)
    println(f"{fields.length()}")
    return 0
EOF
miri run t2.mi -- /tmp/mscratch/a.txt

